{
  "diagnosis": "The option_selection module overweights the primary indication and underweights patient-specific safety facts (e.g., hyperthyroidism, renal history, cardiac history, recent spinal procedures), causing selection of options that are less safe or less appropriate than alternatives.",
  "skills": [
    {
      "id": "indication_safety_balance",
      "text": "When multiple options treat the stated condition, prefer the one with the fewest patient-specific safety concerns; do not choose an option solely because it is a standard first-line therapy if a stated patient fact makes it relatively contraindicated or less appropriate."
    },
    {
      "id": "comorbidity_override",
      "text": "If a stated comorbidity or recent procedure alters the risk-benefit of otherwise indicated options, select the option that remains indicated while minimizing that specific risk; if all indicated options carry some risk, choose the one with the least severe or most manageable risk given the stated facts."
    },
    {
      "id": "avoid_unstated_assumptions",
      "text": "Do not assume a missing patient fact (e.g., allergy, renal function, pregnancy) is present or absent; base selection only on facts explicitly stated in the dialogue."
    }
  ],
  "focus_terms": [
    "patient-specific safety",
    "relative contraindication",
    "comorbidity",
    "indication",
    "risk-benefit"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. When several options are indicated, compare them against all stated patient facts and prefer the option with the fewest or least severe patient-specific safety concerns. If a stated comorbidity or recent procedure makes a standard first-line option relatively contraindicated or less appropriate, select an alternative that remains indicated and safer for that patient. Do not assume missing facts are present or absent."
  }
}

