{
  "diagnosis": "The option_selection module fails to prioritize the safest, most standard first-line agent when multiple options are indicated; it needs a generalized procedure for ranking options by patient-specific safety and guideline-preferred status.",
  "skills": [
    {
      "id": "safety_first_ranking",
      "text": "When several options are indicated, rank them by patient-specific safety first, then by whether the option is the standard or preferred first-line choice for the stated condition; avoid selecting an option merely because it is familiar or commonly used."
    },
    {
      "id": "avoid_contraindicated_or_interacting",
      "text": "Exclude any option that is contraindicated, has a significant interaction with a current medicine, or is less safe for the patient's comorbidities before considering efficacy."
    },
    {
      "id": "prefer_standard_alternative",
      "text": "If the first-line agent is unavailable or unsafe, choose the best-supported alternative for the indication rather than an unrelated or non-indicated option."
    }
  ],
  "focus_terms": [
    "first-line",
    "contraindication",
    "drug interaction",
    "patient-specific safety",
    "standard alternative"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Rank candidate options by: (1) absence of contraindications or significant interactions with current medicines, (2) whether the option is the standard or preferred first-line treatment for the stated condition, and (3) whether it is a well-supported alternative when the first-line agent is unsafe or unavailable. Do not select an option solely because it is familiar or commonly used; exclude any option that is contraindicated, interacting, or less safe for the patient's comorbidities before considering efficacy."
  }
}

{
  "diagnosis": "Option selection failed to prioritize the medication that best matches the patient's active problem and current treatment context, instead choosing options that were less indicated or already superseded.",
  "skills": [
    {
      "id": "indication_first_selection",
      "text": "When choosing among medication options, first identify the patient's active problem and any current medicines. Prefer the option that directly treats the active problem and is appropriate given current therapy. Do not select an option merely because it is familiar or previously used if a better-indicated alternative exists."
    },
    {
      "id": "avoid_redundant_or_unrelated_options",
      "text": "Exclude options that are unrelated to the active problem or that duplicate or conflict with current treatment without added benefit. If the patient is already on a medication for the same indication, consider whether the new option is a necessary change or addition rather than a redundant choice."
    },
    {
      "id": "safety_aware_but_indication_driven",
      "text": "Use safety information to rule out contraindicated options, but do not let safety concerns alone drive selection toward an option with weaker indication. The chosen option should satisfy both indication and patient-specific safety."
    }
  ],
  "focus_terms": [
    "active problem",
    "current medicines",
    "indication",
    "redundant therapy",
    "patient-specific safety"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. First identify the active problem and current medicines. Prefer the option that directly treats the active problem and is appropriate given current therapy. Exclude options that are unrelated to the active problem or that duplicate or conflict with current treatment without added benefit. Use safety information to rule out contraindicated options, but do not let safety concerns alone drive selection toward an option with weaker indication."
  }
}
